import { test, expect } from '@playwright/test';

test.describe('Accessibility - Skip Navigation Links', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://yourwebsite.com'); // Replace with your actual URL
  });

  test('Skip navigation link is the first focusable element', async ({ page }) => {
    await page.keyboard.press('Tab'); // Simulate pressing Tab to focus the first element
    const firstFocusedElement = await page.evaluate(() => document.activeElement);
    const skipLink = await page.getByRole('link', { name: /skip to main content/i }).elementHandle();

    expect(firstFocusedElement).toBe(skipLink);
  });

  test('Skip navigation link is visible and accessible', async ({ page }) => {
    const skipLink = await page.getByRole('link', { name: /skip to main content/i });

    await expect(skipLink).toBeVisible();
    await expect(skipLink).toHaveAttribute('href', '#main-content'); // Assuming the skip link points to an ID
  });
});
